using System;using System.IO;using Por.Core;
public static class DaxRuntimeTests {
 static int n;static void Eq(object a,object b){n++;if(!Equals(a,b))throw new Exception(a+" != "+b);}
 static void WriteDax(string p,byte id,ushort raw,byte[] packed){using(var f=File.Create(p))using(var w=new BinaryWriter(f)){w.Write((ushort)9);w.Write(id);w.Write(0);w.Write(raw);w.Write((ushort)packed.Length);w.Write(packed);}}
 public static void Main(){var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());Directory.CreateDirectory(dir);string old=GDVars.gameDir;try{GDVars.gameDir=dir+Path.DirectorySeparatorChar;GDVars.dsSuppressingInsertDiskFlag=true;DaxIo.ResetArchiveCache();WriteDax(Path.Combine(dir,"TEST.DAX"),9,5,new byte[]{0xfe,77,0,42});ushort sz;byte[] data;DaxIo.LoadDax("TEST",".DAX",9,out sz,out data);Eq(sz,(ushort)5);Eq(data.Length,5);Eq(data[0],(byte)77);Eq(data[1],(byte)77);Eq(data[2],(byte)42);Eq(data[4],(byte)0);DaxIo.LoadDax("TEST",".DAX",8,out sz,out data);Eq(sz,(ushort)0);Eq(data,null);DaxIo.LoadDax("MISSING",".DAX",9,out sz,out data);Eq(sz,(ushort)0);Eq(data,null);GDVars.virtualDisk=2;DaxIo.PushState(5);Eq(GDVars.virtualDisk,(byte)5);DaxIo.PopState();Eq(GDVars.virtualDisk,(byte)2);Eq(DaxIo.FamilyUsable(1),false);Eq(DaxIo.ArchiveName("ECL1"),"ECL1");}finally{GDVars.gameDir=old;DaxIo.ResetArchiveCache();Directory.Delete(dir,true);}Console.WriteLine("DAX runtime archive assertions passed: "+n);}
}
